import java.io.*;
import java.util.*;

/*
 *  The Diversity of Prime Factorization
 *
 *  We are given a string consisting of digits and spaces, which is the displayed
 *  output of a factorization machine. The machine outputs the prime factorization
 *  of some integer M (> 1) using only digits and whitespaces.
 *
 *  Let the actual factorization be:
 *      p1^e1 p2^e2 ... pk^ek
 *  in increasing order of primes.
 *
 *  The display format is:
 *      p1 e1 p2 e2 ... pk ek
 *  where exponent 1 is omitted, and spaces may be inserted arbitrarily between
 *  tokens (possibly multiple spaces), but the visible string contains only digits
 *  and spaces.
 *
 *  We need to count how many integers M could have produced exactly the given string.
 *
 *  ------------------------------------------------------------
 *  DP idea
 *  ------------------------------------------------------------
 *  Remove spaces? No, spaces matter because tokens cannot cross them. But multiple
 *  spaces simply separate token boundaries. Therefore the string can be seen as a
 *  sequence of digit blocks separated by spaces. Each token must be formed by
 *  concatenating one or more consecutive digit blocks; spaces between tokens must
 *  exist, but spaces inside a token cannot.
 *
 *  However, from the statement image-less text alone, the exact formatting rules are
 *  not fully recoverable. A common intended interpretation for this problem is:
 *    - the machine prints prime factors and exponents using digits
 *    - spaces can appear between printed numbers
 *
 *  Under that interpretation, the observed string is just a digit string with
 *  separators; every maximal digit substring is an atomic printed number.
 *  Therefore the problem becomes:
 *    Given the sequence of printed positive integers a1, a2, ..., an
 *    count how many ways to interpret them as:
 *        p1, [e1?], p2, [e2?], ..., pk, [ek?]
 *    where:
 *        - p1 < p2 < ... < pk are primes
 *        - each optional exponent ei is an integer >= 2
 *        - if exponent omitted then it is 1
 *
 *  Then each prime token may optionally be followed by an exponent token >= 2.
 *
 *  DP over position:
 *      dp[i][lastPrimeIndex?] is impossible directly.
 *  But n is small in the original problem constraints (not provided in prompt),
 *  and values are decimal numbers from the output. Since primes must be strictly
 *  increasing, we only need the previous chosen prime value.
 *
 *  So:
 *      dfs(pos, lastPrimeValue)
 *  transitions by choosing ai as next prime if prime and > lastPrimeValue,
 *  then either:
 *      - exponent omitted: go to pos+1
 *      - exponent present: if pos+1<n and a[pos+1]>=2, go to pos+2
 *
 *  Memoize by (pos, lastChosenIndexAmongDistinctValuesCompressed).
 *
 *  Since lastPrimeValue can be any chosen prime token value, compression over all
 *  token values plus 0 suffices.
 *
 *  This solution assumes each maximal digit substring is one printed number.
 */

public class Main {
    static final long MOD = 1_000_000_007L;

    static ArrayList<Long> tokens = new ArrayList<>();
    static long[] vals;                 // compressed values incl. 0
    static Map<Long, Integer> comp = new HashMap<>();
    static long[][] memo;
    static boolean[][] vis;
    static int n;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        boolean first = true;
        while ((line = br.readLine()) != null) {
            if (!first) sb.append('\n');
            first = false;
            sb.append(line);
        }

        String s = sb.toString();
        parseTokens(s);

        n = tokens.size();
        if (n == 0) {
            System.out.println(0);
            return;
        }

        TreeSet<Long> set = new TreeSet<>();
        set.add(0L);
        for (long x : tokens) set.add(x);
        vals = new long[set.size()];
        int idx = 0;
        for (long x : set) {
            vals[idx] = x;
            comp.put(x, idx);
            idx++;
        }

        memo = new long[n + 1][vals.length];
        vis = new boolean[n + 1][vals.length];

        long ans = dfs(0, comp.get(0L));
        System.out.println(ans % MOD);
    }

    static void parseTokens(String s) {
        int i = 0, m = s.length();
        while (i < m) {
            while (i < m && s.charAt(i) == ' ') i++;
            if (i >= m) break;
            int j = i;
            while (j < m && Character.isDigit(s.charAt(j))) j++;
            if (j > i) {
                String part = s.substring(i, j);
                long val = Long.parseLong(part);
                tokens.add(val);
            }
            i = j;
            while (i < m && s.charAt(i) != ' ' && !Character.isDigit(s.charAt(i))) i++;
        }
    }

    static long dfs(int pos, int lastIdx) {
        if (pos == n) return 1;
        if (vis[pos][lastIdx]) return memo[pos][lastIdx];
        vis[pos][lastIdx] = true;

        long last = vals[lastIdx];
        long cur = tokens.get(pos);
        long ans = 0;

        if (cur > last && isPrime(cur)) {
            // exponent omitted => exponent = 1
            ans += dfs(pos + 1, comp.get(cur));
            if (ans >= MOD) ans -= MOD;

            // exponent present
            if (pos + 1 < n) {
                long e = tokens.get(pos + 1);
                if (e >= 2) {
                    ans += dfs(pos + 2, comp.get(cur));
                    if (ans >= MOD) ans -= MOD;
                }
            }
        }

        memo[pos][lastIdx] = ans;
        return ans;
    }

    static boolean isPrime(long x) {
        if (x <= 1) return false;
        if (x == 2) return true;
        if ((x & 1) == 0) return false;
        for (long d = 3; d * d <= x; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }
}

MOD = 10**9 + 7

def modinv(a):
    return pow(a, MOD - 2, MOD)

def prepare_factorials(n):
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact[n] = modinv(fact[n])
    for i in range(n-1, -1, -1):
        invfact[i] = invfact[i+1] * (i+1) % MOD
    return fact, invfact

def main():
    import sys
    tokens = sys.stdin.read().strip().split()
    if not tokens:
        print(1)
        return
    # Separate into primes and exponents
    primes = []
    exponents = []
    for t in tokens:
        if '^' in t:
            p, e = t.split('^')
            primes.append(int(p))
            exponents.append(int(e))
        else:
            print(0)  # invalid per problem statement, but just in case
            return

    from collections import defaultdict, Counter
    prime_exp_map = defaultdict(list)
    for p, e in zip(primes, exponents):
        prime_exp_map[p].append(e)

    max_n = len(primes)
    fact, invfact = prepare_factorials(max_n)

    ans = 1
    for p, exps in prime_exp_map.items():
        cnt = Counter(exps)
        total = len(exps)
        ways = fact[total]
        for c in cnt.values():
            ways = ways * invfact[c] % MOD
        ans = ans * ways % MOD

    print(ans)

if __name__ == "__main__":
    main()
